// Firmas de los representantes legales para los documentos de cierre y la hoja
// de servicio. NO van en /public: solo las entrega /api/ordenes/[id]/hoja a
// quien tiene acceso a la orden. Importar únicamente desde código de servidor.

const FIRMAS: Record<string, string> = {
  TOLTECATL: "data:image/png;base64,",
  BOCAM: "data:image/png;base64,",
}

export function firmaRepresentante(claveEmpresa: string): string {
  return FIRMAS[claveEmpresa] ?? ""
}
